// Lookups into the static timetable snapshot (static.json, generated by `npm run gtfs:sync`).
import type { LineId } from '@/lib/trains/types';
import { lineForRoute } from '@/lib/trains/lines';
import data from './static.json';

export interface Station {
  id: string;
  name: string;
  /** Line color families that stop here, e.g. Grand Central → hudson, harlem, new-haven */
  lines: LineId[];
}

const stations: Record<string, { name: string; routes: string[] }> = data.stations;
const routes: Record<string, { name: string; color: string }> = data.routes;
const peakTrains = new Set(data.peakTrains);
const LINE_ORDER: LineId[] = ['hudson', 'harlem', 'new-haven'];

export const STATIC_GENERATED_AT = data.generatedAt;

export function stationName(id: string): string {
  return stations[id]?.name ?? `Station ${id}`;
}

/** All stations with service, alphabetical, for the station search */
export function stationsSorted(): Station[] {
  return Object.entries(stations)
    .map(([id, s]) => {
      const lines = new Set(s.routes.map(lineForRoute));
      return { id, name: s.name, lines: LINE_ORDER.filter((l) => lines.has(l)) };
    })
    .sort((a, b) => a.name.localeCompare(b.name));
}

export function routeName(routeId: string): string {
  return routes[routeId]?.name ?? 'Metro-North';
}

/** Peak/off-peak, looked up by train number */
export function isPeakTrain(trainNumber: string): boolean {
  return peakTrains.has(trainNumber);
}
